update.sql:
create table ClientApplicationAllowedRedirectURIs (
   clientApplication bigint not null,
    redirectURI varchar(255) not null,
    primary key (clientApplication, redirectURI)
);

create table ClientApplicationAuthorizationCodeScopes (
   authorizationCode bigint not null,
    scope varchar(255) not null,
    primary key (authorizationCode, scope)
);

create table ClientApplicationAccessTokenScopes (
   token bigint not null,
    scope varchar(255) not null,
    primary key (token, scope)
);
